def parameter_counts(in_dim, out_dim, rank):
    if any(not isinstance(x,int) or x <= 0 for x in (in_dim,out_dim,rank)):
        raise ValueError('dimensions must be positive integers')
    return {'frozen':in_dim*out_dim+out_dim, 'trainable':rank*(in_dim+out_dim)}

exercise.tests:
