def ppo_surrogate(ratios,advantages,eps=0.2):
    if len(ratios)!=len(advantages) or not ratios or eps<0: raise ValueError('invalid inputs')
    values=[]
    for r,a in zip(ratios,advantages):
        clipped=max(1-eps,min(1+eps,r))
        values.append(min(r*a,clipped*a))
    return sum(values)/len(values)

import math
def dpo_loss(pc, pr, rc, rr, beta):
    z=beta*((pc-rc)-(pr-rr))
    return max(-z,0.0)+math.log1p(math.exp(-abs(z)))

